CASE Phase OF
  0: (* Red *)
    Red_Light := TRUE; Green_Light := FALSE; Amber_Light := FALSE;
    Red_Timer(IN := TRUE, PT := T#30s);
    IF Red_Timer.Q THEN Phase := 1; Red_Timer(IN:=FALSE); END_IF;
  1: (* Green *)
    Red_Light := FALSE; Green_Light := TRUE;
    Green_Timer(IN := TRUE, PT := T#25s);
    IF Green_Timer.Q THEN Phase := 2; Green_Timer(IN:=FALSE); END_IF;
  2: (* Amber *)
    Green_Light := FALSE; Amber_Light := TRUE;
    Amber_Timer(IN := TRUE, PT := T#5s);
    IF Amber_Timer.Q THEN Phase := 0; Amber_Timer(IN:=FALSE); END_IF;
  ELSE:
    Red_Light := TRUE; Green_Light := FALSE;
    Amber_Light := FALSE; Phase := 0;
END_CASE;
